func And(predicates ...predicate.PointLedger) predicate.PointLedger {
	return predicate.PointLedger(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PointLedger) predicate.PointLedger {
	return predicate.PointLedger(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PointLedger) predicate.PointLedger {
	return predicate.PointLedger(sql.NotPredicates(p))
}
